110	/** Open an ssh2 connection to a server, run `fn`, and always end the connection. */
111	async function withSsh<T>(
112	  target: { host: string; port: number },
113	  password: string,
114	  fn: (conn: SshClient) => Promise<T>
115	): Promise<T> {
116	  const conn = new SshClient();
117	  await new Promise<void>((resolve, reject) => {
118	    const timer = setTimeout(() => {
119	      try {
120	        conn.end();
121	      } catch {
122	        /* best effort */
123	      }
124	      reject(new Error(`SSH connect timed out after ${Math.round(SSH_CONNECT_TIMEOUT_MS / 1000)}s`));
125	    }, SSH_CONNECT_TIMEOUT_MS);
126	    conn
127	      .on("ready", () => {
128	        clearTimeout(timer);
129	        resolve();
130	      })
131	      .on("error", (e) => {
132	        clearTimeout(timer);
133	        reject(e);
134	      })
135	      .connect({
136	        host: target.host,
137	        port: target.port,
138	        username: "root",
139	        password,
140	        readyTimeout: SSH_CONNECT_TIMEOUT_MS,
141	      });
142	  });
143	  try {
144	    return await fn(conn);
145	  } finally {
146	    try {
147	      conn.end();
148	    } catch {
149	      /* best effort */
150	    }
151	  }
152	}
