154	/**
155	 * Really issue a Let's Encrypt certificate for `cert.domain` by SSHing into the
156	 * customer's own VM (same host/port/root-password derivation as lib/sftp) and
157	 * driving certbot in --standalone mode. Throws on any failure so the caller's
158	 * catch marks the cert FAILED with the reason.
159	 *
160	 * Steps on the customer VM:
161	 *   1. Detect the package manager (apt-get / dnf) and ensure `certbot` exists,
162	 *      installing it if missing.
163	 *   2. Confirm TCP port 80 is free (standalone binds it for the HTTP-01
164	 *      challenge) — surface a clear error otherwise.
165	 *   3. certbot certonly --standalone -n --agree-tos -m <email> -d <domain>.
166	 *   4. Read the real notAfter from the issued fullchain via `openssl x509
167	 *      -enddate`, falling back to now+90d if that can't be parsed.
168	 *
169	 * Returns the issuedAt/expiresAt to persist.
170	 */
171	async function issueRealCertificate(
172	  cert: SslCertificate
173	): Promise<{ issuedAt: Date; expiresAt: Date }> {
174	  const domain = cert.domain;
175	  assertSafeDomain(domain);
176	
177	  if (!cert.serverId) {
178	    throw new Error("Certificate is not attached to a server.");
179	  }
180	
181	  // Load exactly the fields connectionTarget()/SSH need (mirrors lib/sftp usage).
182	  const server = await db.server.findUnique({
183	    where: { id: cert.serverId },
184	    select: {
185	      id: true,
186	      rootPassword: true,
187	      rootPasswordEnc: true,
188	      sshPort: true,
189	      dedicatedIp: { select: { address: true } },
190	    },
191	  });
192	  if (!server) throw new Error(`Server ${cert.serverId} not found.`);
193	
194	  const target = connectionTarget(server as SftpServer);
195	  if (!target) {
196	    throw new Error("Server is not reachable yet — connection details are pending.");
197	  }
198	  const rootPassword = serverRootPassword(server);
199	  if (!rootPassword) throw new Error("Server has no root password set.");
200	
201	  const qDomain = shellQuote(domain);
202	  const qEmail = shellQuote(CERTBOT_EMAIL);
203	
204	  return withSsh(target, rootPassword, async (conn) => {
205	    // 1. Ensure certbot is present. `command -v` is portable; install only if missing.
206	    const have = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
207	    if (have.stdout.trim() !== "yes") {
208	      // Pick the installer from whichever package manager exists.
209	      const pm = await sshExec(
210	        conn,
211	        "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
212	          "elif command -v dnf >/dev/null 2>&1; then echo dnf; else echo none; fi",
213	        PROBE_TIMEOUT_MS
214	      );
215	      const which = pm.stdout.trim();
216	      let installCmd: string;
217	      if (which === "apt") {
218	        installCmd = "DEBIAN_FRONTEND=noninteractive apt-get update -y && apt-get install -y certbot";
219	      } else if (which === "dnf") {
220	        installCmd = "dnf install -y certbot";
221	      } else {
222	        throw new Error("No supported package manager (apt-get/dnf) found to install certbot.");
223	      }
224	      const inst = await sshExec(conn, installCmd, CERTBOT_TIMEOUT_MS);
225	      if (inst.code !== 0) {
226	        throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 300)}`);
227	      }
228	      // Re-check that certbot is now on PATH.
229	      const recheck = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
230	      if (recheck.stdout.trim() !== "yes") {
231	        throw new Error("certbot still not available after install.");
232	      }
233	    }
234	
235	    // 2. Standalone needs port 80. If something is already listening, bail with a
236	    //    clear message rather than letting certbot fail cryptically. (We default to
237	    //    --standalone; --webroot would only be used if a docroot were known.)
238	    const portCheck = await sshExec(
239	      conn,
240	      "ss -ltnH 'sport = :80' 2>/dev/null | head -n1 || true",
241	      PROBE_TIMEOUT_MS
242	    );
243	    if (portCheck.stdout.trim().length > 0) {
244	      throw new Error(
245	        "Port 80 is in use by another service; free it (or configure webroot issuance) before requesting a standalone certificate."
246	      );
247	    }
248	
249	    // 3. Issue. --standalone spins up certbot's own HTTP-01 responder on :80.
250	    const certbotCmd =
251	      `certbot certonly --standalone -n --agree-tos -m ${qEmail} -d ${qDomain}`;
252	    const run = await sshExec(conn, certbotCmd, CERTBOT_TIMEOUT_MS);
253	    const combined = `${run.stdout}\n${run.stderr}`;
254	    // certbot exits 0 on success (including "Certificate not yet due for renewal").
255	    const succeeded =
256	      run.code === 0 &&
257	      /Congratulations|Successfully received certificate|not yet due for renewal|Certificate is saved/i.test(combined);
258	    if (!succeeded) {
259	      throw new Error(`certbot failed: ${combined.trim().slice(0, 400)}`);
260	    }
261	
262	    // 4. Prefer the real notAfter from the issued chain; fall back to now+90d.
263	    const now = new Date();
264	    let expiresAt = new Date(now.getTime() + CERT_LIFETIME_MS);
265	    const live = `/etc/letsencrypt/live/${domain}/fullchain.pem`;
266	    const enddate = await sshExec(
267	      conn,
268	      `openssl x509 -enddate -noout -in ${shellQuote(live)} 2>/dev/null || true`,
269	      PROBE_TIMEOUT_MS
270	    );
271	    const m = enddate.stdout.match(/notAfter=(.+)/);
272	    if (m) {
273	      const parsed = new Date(m[1].trim());
274	      if (!Number.isNaN(parsed.getTime())) expiresAt = parsed;
275	    }
276	
277	    return { issuedAt: now, expiresAt };
278	  });
279	}
