1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { AutoRefresh } from "@/components/AutoRefresh";
4	import { PageHeader } from "@/components/ui/primitives";
5	import { SslManager, type CertRow, type ServerOption } from "@/components/customer/SslManager";
6	
7	export const dynamic = "force-dynamic";
8	
9	export default async function SslPage() {
10	  const user = await requireUser();
11	
12	  const [certificates, servers] = await Promise.all([
13	    db.sslCertificate.findMany({
14	      where: { userId: user.id },
15	      orderBy: { createdAt: "desc" },
16	    }),
17	    db.server.findMany({
18	      where: { userId: user.id },
19	      orderBy: { createdAt: "desc" },
20	    }),
21	  ]);
22	
23	  const serverName = new Map(servers.map((s) => [s.id, s.hostname]));
24	
25	  const rows: CertRow[] = certificates.map((c) => ({
26	    id: c.id,
27	    domain: c.domain,
28	    status: c.status,
29	    issuer: c.issuer,
30	    autoRenew: c.autoRenew,
31	    serverName: c.serverId ? serverName.get(c.serverId) ?? null : null,
32	    issuedAt: c.issuedAt ? c.issuedAt.toISOString() : null,
33	    expiresAt: c.expiresAt ? c.expiresAt.toISOString() : null,
34	    lastError: c.lastError,
35	  }));
36	
37	  // Certificate issuance needs a live, DNS-pointed server, so only offer running ones.
38	  const serverOptions: ServerOption[] = servers
39	    .filter((s) => s.status === "RUNNING")
40	    .map((s) => ({ id: s.id, hostname: s.hostname }));
41	
42	  const transitional = certificates.some((c) => ["PENDING", "ISSUING"].includes(c.status));
43	
44	  return (
45	    <div className="space-y-6">
46	      {transitional && <AutoRefresh />}
47	      <PageHeader
48	        title="SSL Certificates"
49	        sub="One-click Let's Encrypt certificates for domains pointed at your servers."
50	      />
51	      <SslManager certificates={rows} servers={serverOptions} />
52	    </div>
53	  );
54	}
55

  }
}

/**
 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
 * killed worker leaves a job RUNNING forever, which permanently blocks the
 * server's "one in-flight job" guard and strands it in a transitional state.
 */
async function reapStuckJobs() {
  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
  for (const job of stuck) {
    const retriable = job.attempts < MAX_ATTEMPTS;
    await db.job.update({
      where: { id: job.id },
      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
    });
    if (!retriable) {
      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
      if (job.serverId) {
        const s = await db.server.findUnique({ where: { id: job.serverId } });
