import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { connectionTarget, serverRootPassword, type SftpServer } from "../lib/sftp";
import { Client as SshClient } from "ssh2";
import { connect as tlsConnect } from "node:tls";
import type { Job, SslCertificate } from "@prisma/client";

/**
 * SSL certificate lifecycle: issuance (SSL_ISSUE), renewal, and reconciliation.
 *
 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
 *   SSL_ISSUE: sslIssue,
 * and put the lifecycle sweep on the loop's timer (same shape as
 * `lastBackupSweep` / `scheduledBackupSweep`):
 *   import { sslIssue, sslSweep } from "./ssl";
 *   let lastSslSweep = 0;
 *   if (Date.now() - lastSslSweep > 30 * 60_000) {
 *     lastSslSweep = Date.now();
 *     try { await sslSweep(); } catch (e) { console.error("[ssl] sweep error", e); }
 *   }
 *
 * Until 2026-07-26 `sslIssue` was the ONLY thing in this file. Certificates were
 * issued once and then never looked at again, so:
 *   - every certificate silently died at 90 days while the dashboard kept a green
 *     pulsing ACTIVE dot beside a neutral "Expires" date (EXPIRED was documented
 *     in the schema and written by nothing);
 *   - a row could sit in ISSUING forever if the worker was restarted mid-issue,
 *     and the customer could not even delete it;
 *   - `expiresAt` could be a computed now+90d guess rather than an observed date.
 * `sslSweep` fixes all three, and `verifyServed` reads back what is actually
 * being served so "active" means a certificate we have really seen.
 *
 * SAFETY: actually issuing a Let's Encrypt cert means SSHing to the customer's
 * VM and running certbot against a live, DNS-pointed domain. The real path runs
 * only when we're NOT in SANDBOX and ENABLE_REAL_SSL === "1"; in SANDBOX the
 * handler simulates, and outside SANDBOX without the flag it FAILS LOUDLY rather
 * than claiming a certificate that does not exist.
 */

/**
 * A Let's Encrypt certificate is valid for 90 days. Used ONLY by the SANDBOX
 * simulation below, which labels itself as such. The real path must never
 * compute an expiry — see readObservedExpiry().
 */
const SANDBOX_CERT_LIFETIME_MS = 90 * 86400_000;

/**
 * ACME account / contact email passed to certbot (`-m`). Let's Encrypt uses it
 * for expiry warnings. Override with CERTBOT_EMAIL; falls back to a constant.
 */
const CERTBOT_EMAIL = process.env.CERTBOT_EMAIL || "ssl-admin@nxeon.local";

/** Overall SSH connect timeout, and per-certbot-command timeout. */
const SSH_CONNECT_TIMEOUT_MS = 15_000;
const CERTBOT_TIMEOUT_MS = 120_000;
/** Shorter budget for the quick pre-flight/install probes. */
const PROBE_TIMEOUT_MS = 60_000;

// ---------------------------------------------------------------------------
// Lifecycle tuning
// ---------------------------------------------------------------------------

/**
 * Renew when 21 days or less remain. Two hard constraints pin this number:
 *  - certbot only renews a lineage when fewer than 30 days remain. Asking
 *    earlier is a no-op ("Certificate not yet due for renewal"), so a 30-day
 *    lead would SSH into the customer's VM every sweep and achieve nothing.
 *  - the retry ladder below spends up to ~4.25 days inside one rate-limit
 *    window, so we need several windows of runway before the cert actually dies.
 * 21 days sits inside certbot's own window and still leaves three weeks of slack.
 */
const RENEW_LEAD_MS = 21 * 86400_000;

/**
 * Rolling window and hard cap for issue attempts against ONE hostname.
 *
 * Let's Encrypt allows 5 duplicate certificates (identical hostname set) per
 * week. Exceeding it locks the customer out of HTTPS for a full week — far worse
 * than renewing a day late — so we stop at 4 and leave one slot for the
 * customer's own manual "Renew now".
 */
const ISSUE_WINDOW_MS = 7 * 86400_000;
const MAX_ISSUE_ATTEMPTS_PER_WINDOW = 4;

/**
 * Wait required before the next attempt, indexed by how many attempts have
 * already been made for this hostname inside the current window: the first is
 * immediate, then 6h / 24h / 72h. This is what makes the sweep incapable of
 * looping — a sweep that runs every 30 minutes still cannot produce more than
 * four certbot runs per hostname per week.
 */
const RENEW_BACKOFF_MS = [0, 6 * 3600_000, 24 * 3600_000, 72 * 3600_000];

/**
 * How long a PENDING row may sit with no SSL_ISSUE job at all before we call it
 * lost. A row that IS attached to a queued job is never aged out no matter how
 * long it waits — the queue is serial platform-wide and a genuine 40-minute wait
 * behind a MIGRATE is not a failure (the dashboard explains the wait instead).
 */
const ORPHAN_PENDING_MS = 15 * 60_000;

/**
 * Grace after a terminal SSL_ISSUE job before we declare an ISSUING row orphaned.
 * Guards the tiny window between the handler returning and index.ts writing DONE.
 */
const ORPHAN_GRACE_MS = 2 * 60_000;

/** TLS read-back of the certificate actually being served on :443. */
const TLS_PROBE_TIMEOUT_MS = 5_000;

/**
 * Sweeps run INLINE in the worker's strictly serial `for(;;)` loop, so every
 * second spent here is a second no customer job runs. These caps keep a sweep
 * bounded well under a minute even with a large certificate table — the whole
 * point of P1-38/P1-1 is that a slow sweep is itself an outage.
 */
const MAX_CERTS_PER_SWEEP = 60;
const PROBE_BUDGET_MS = 25_000;

/**
 * `Job.step` doubles as the machine-readable outcome of an SSL_ISSUE attempt.
 * We need it because the rate-limit counter must distinguish attempts that
 * really reached Let's Encrypt from ones that died locally (certbot missing,
 * port 80 busy, SSH refused). Without the distinction, a customer whose port 80
 * is occupied would be locked out for a week by failures LE never even saw.
 *
 * NOTE: the two "did not reach LE" values are duplicated in lib/actions-ssl.ts
 * (which cannot import this module — it would pull ssh2 into the Next bundle).
 * Keep them in sync.
 */
export const SSL_STEP_ISSUED = "certificate issued";
export const SSL_STEP_ACME_FAILED = "failed at the certbot/ACME step";
export const SSL_STEP_PREFLIGHT_FAILED = "failed before contacting Let's Encrypt";
export const SSL_STEP_SANDBOX = "simulated (sandbox)";

/** Stable prefix so a repeated sweep can recognise its own pause note. */
const RENEWAL_PAUSED_PREFIX = "Automatic renewal is paused";

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[ssl] notify failed", e);
  }
}

/**
 * Send `title` at most once per `withinMs` for this user. The sweep runs every
 * 30 minutes; without this a customer with one un-renewable certificate would
 * collect ~50 identical notifications a day and stop reading any of them.
 */
async function notifyOnce(
  userId: string,
  title: string,
  body: string,
  withinMs: number
): Promise<void> {
  const recent = await db.notification.findFirst({
    where: { userId, title, createdAt: { gt: new Date(Date.now() - withinMs) } },
    select: { id: true },
  });
  if (recent) return;
  await notify(userId, title, body, "/dashboard/ssl");
}

// ----------------------------------------------------------------------------
// Real issuance path (SSH + certbot). Only reachable when
// `!SANDBOX && ENABLE_REAL_SSL === "1"` — see the guard in sslIssue().
// ----------------------------------------------------------------------------

type SshResult = { code: number | null; stdout: string; stderr: string };

/**
 * Tracks whether an attempt got as far as invoking certbot. Passed in by
 * reference so the value survives the throw that unwinds out of the SSH block —
 * the rate-limit counter needs it (see SSL_STEP_* above).
 */
type IssuePhase = { reachedAcme: boolean };

/**
 * Single-quote a value for safe interpolation into a POSIX shell command.
 * We already restrict the domain to a strict charset below, but everything that
 * reaches a remote shell is quoted defensively regardless.
 */
function shellQuote(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`;
}

/** Domains must look like real hostnames before we hand them to certbot. */
function assertSafeDomain(domain: string): void {
  if (!/^(?=.{1,253}$)([a-zA-Z0-9-]{1,63}\.)+[a-zA-Z]{2,63}$/.test(domain)) {
    throw new Error(`Refusing to issue for an unexpected domain: ${domain}`);
  }
}

/**
 * Run one command on an already-connected ssh2 client, capturing stdout/stderr
 * and the exit code. Rejects on transport error or if the command exceeds
 * `timeoutMs` (the channel is torn down so a hung certbot can't wedge the worker).
 */
function sshExec(conn: SshClient, command: string, timeoutMs: number): Promise<SshResult> {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      let settled = false;
      const timer = setTimeout(() => {
        if (settled) return;
        settled = true;
        try {
          stream.close();
        } catch {
          /* best effort */
        }
        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
      }, timeoutMs);

      stream
        .on("close", (code: number | null) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve({ code, stdout, stderr });
        })
        .on("data", (d: Buffer) => {
          stdout += d.toString("utf8");
        })
        .stderr.on("data", (d: Buffer) => {
          stderr += d.toString("utf8");
        });
    });
  });
}

/** Open an ssh2 connection to a server, run `fn`, and always end the connection. */
async function withSsh<T>(
  target: { host: string; port: number },
  password: string,
  fn: (conn: SshClient) => Promise<T>
): Promise<T> {
  const conn = new SshClient();
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => {
      try {
        conn.end();
      } catch {
        /* best effort */
      }
      reject(new Error(`SSH connect timed out after ${Math.round(SSH_CONNECT_TIMEOUT_MS / 1000)}s`));
    }, SSH_CONNECT_TIMEOUT_MS);
    conn
      .on("ready", () => {
        clearTimeout(timer);
        resolve();
      })
      .on("error", (e) => {
        clearTimeout(timer);
        reject(e);
      })
      .connect({
        host: target.host,
        port: target.port,
        username: "root",
        password,
        readyTimeout: SSH_CONNECT_TIMEOUT_MS,
      });
  });
  try {
    return await fn(conn);
  } finally {
    try {
      conn.end();
    } catch {
      /* best effort */
    }
  }
}

/**
 * Read the certificate's REAL notAfter off the customer's VM.
 *
 * There is deliberately no fallback. The previous version defaulted to
 * `now + 90 days` whenever `openssl x509 -enddate` could not be parsed, which is
 * how a row could claim ACTIVE with an expiry nobody had ever observed — the same
 * class of lie as the simulated-success branch. If we cannot read the date, the
 * attempt is a failure and says so; re-requesting is cheap because certbot reuses
 * a still-valid certificate without asking Let's Encrypt again.
 */
async function readObservedExpiry(conn: SshClient, domain: string): Promise<Date> {
  const live = `/etc/letsencrypt/live/${domain}/fullchain.pem`;
  const enddate = await sshExec(
    conn,
    `openssl x509 -enddate -noout -in ${shellQuote(live)} 2>&1 || true`,
    PROBE_TIMEOUT_MS
  );
  const m = enddate.stdout.match(/notAfter=(.+)/);
  const parsed = m ? new Date(m[1].trim()) : null;
  if (!parsed || Number.isNaN(parsed.getTime())) {
    throw new Error(
      `certbot reported success but the certificate's real expiry could not be read back from ${live} ` +
        `(${(enddate.stdout || "no output").trim().slice(0, 160)}). We do not report a certificate as ` +
        `active on a guessed expiry date, so this attempt is recorded as failed. Requesting again is safe.`
    );
  }
  return parsed;
}

/**
 * Really issue a Let's Encrypt certificate for `cert.domain` by SSHing into the
 * customer's own VM (same host/port/root-password derivation as lib/sftp) and
 * driving certbot in --standalone mode. Throws on any failure so the caller's
 * catch marks the cert with the reason.
 *
 * Steps on the customer VM:
 *   1. Detect the package manager (apt-get / dnf) and ensure `certbot` exists,
 *      installing it if missing.
 *   2. Confirm TCP port 80 is free (standalone binds it for the HTTP-01
 *      challenge) — surface a clear error otherwise.
 *   3. certbot certonly --standalone -n --agree-tos -m <email> -d <domain>.
 *   4. Read the real notAfter back out of the issued fullchain (no guessing).
 *
 * Everything before step 3 sets nothing on `phase`; step 3 flips
 * `phase.reachedAcme` so a local pre-flight failure is not counted against the
 * Let's Encrypt weekly limit.
 */
async function issueRealCertificate(
  cert: SslCertificate,
  phase: IssuePhase
): Promise<{ issuedAt: Date; expiresAt: Date }> {
  const domain = cert.domain;
  assertSafeDomain(domain);

  if (!cert.serverId) {
    throw new Error("Certificate is not attached to a server.");
  }

  // Load exactly the fields connectionTarget()/SSH need (mirrors lib/sftp usage).
  const server = await db.server.findUnique({
    where: { id: cert.serverId },
    select: {
      id: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (!server) throw new Error(`Server ${cert.serverId} not found.`);

  const target = connectionTarget(server as SftpServer);
  if (!target) {
    throw new Error("Server is not reachable yet — connection details are pending.");
  }
  const rootPassword = serverRootPassword(server);
  if (!rootPassword) throw new Error("Server has no root password set.");

  const qDomain = shellQuote(domain);
  const qEmail = shellQuote(CERTBOT_EMAIL);

  return withSsh(target, rootPassword, async (conn) => {
    // 1. Ensure certbot is present. `command -v` is portable; install only if missing.
    const have = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
    if (have.stdout.trim() !== "yes") {
      // Pick the installer from whichever package manager exists.
      const pm = await sshExec(
        conn,
        "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
          "elif command -v dnf >/dev/null 2>&1; then echo dnf; else echo none; fi",
        PROBE_TIMEOUT_MS
      );
      const which = pm.stdout.trim();
      let installCmd: string;
      if (which === "apt") {
        installCmd = "DEBIAN_FRONTEND=noninteractive apt-get update -y && apt-get install -y certbot";
      } else if (which === "dnf") {
        installCmd = "dnf install -y certbot";
      } else {
        throw new Error("No supported package manager (apt-get/dnf) found to install certbot.");
      }
      const inst = await sshExec(conn, installCmd, CERTBOT_TIMEOUT_MS);
      if (inst.code !== 0) {
        throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 300)}`);
      }
      // Re-check that certbot is now on PATH.
      const recheck = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
      if (recheck.stdout.trim() !== "yes") {
        throw new Error("certbot still not available after install.");
      }
    }

    // 2. Standalone needs port 80. If something is already listening, bail with a
    //    clear message rather than letting certbot fail cryptically. (We default to
    //    --standalone; --webroot would only be used if a docroot were known.)
    const portCheck = await sshExec(
      conn,
      "ss -ltnH 'sport = :80' 2>/dev/null | head -n1 || true",
      PROBE_TIMEOUT_MS
    );
    if (portCheck.stdout.trim().length > 0) {
      throw new Error(
        "Port 80 is in use by another service; free it (or configure webroot issuance) before requesting a standalone certificate."
      );
    }

    // 3. Issue. --standalone spins up certbot's own HTTP-01 responder on :80.
    //    From here on the attempt may have consumed a Let's Encrypt slot.
    const certbotCmd =
      `certbot certonly --standalone -n --agree-tos -m ${qEmail} -d ${qDomain}`;
    phase.reachedAcme = true;
    const run = await sshExec(conn, certbotCmd, CERTBOT_TIMEOUT_MS);
    const combined = `${run.stdout}\n${run.stderr}`;
    // certbot exits 0 on success (including "Certificate not yet due for renewal").
    const succeeded =
      run.code === 0 &&
      /Congratulations|Successfully received certificate|not yet due for renewal|Certificate is saved/i.test(combined);
    if (!succeeded) {
      throw new Error(`certbot failed: ${combined.trim().slice(0, 400)}`);
    }

    // 4. The expiry we persist is the one on the certificate, never a guess.
    const expiresAt = await readObservedExpiry(conn, domain);
    return { issuedAt: new Date(), expiresAt };
  });
}

// ----------------------------------------------------------------------------
// Read back what is actually being served (no SSH, no certbot, no ACME).
// ----------------------------------------------------------------------------

type ServedCert =
  | { ok: true; notAfter: Date; coversDomain: boolean }
  | { ok: false; reason: string };

function tlsErrorReason(e: any): string {
  const code = String(e?.code ?? "");
  if (code === "ECONNREFUSED") return "nothing is listening on port 443";
  if (code === "ENOTFOUND" || code === "EAI_AGAIN") return "the domain does not resolve in DNS";
  if (code === "ETIMEDOUT") return "the connection to port 443 timed out";
  if (code === "ECONNRESET") return "the connection was reset before TLS finished";
  if (code === "EHOSTUNREACH" || code === "ENETUNREACH") return "the host is unreachable";
  return (String(e?.message ?? e) || code || "the TLS connection failed").slice(0, 140);
}

/** Does a certificate name (possibly `*.example.com`) cover `domain`? */
function hostMatches(name: string, domain: string): boolean {
  const n = name.trim().toLowerCase();
  const d = domain.trim().toLowerCase();
  if (!n) return false;
  if (n === d) return true;
  if (n.startsWith("*.")) {
    // A wildcard covers exactly one label, so the label counts must match.
    return d.endsWith(n.slice(1)) && d.split(".").length === n.split(".").length;
  }
  return false;
}

/**
 * Open a plain TLS connection to `domain:443` and read the certificate the
 * public internet is actually being handed.
 *
 * This is the cheap, honest half of "is it really active": certbot --standalone
 * OBTAINS a certificate but does not install it into nginx/apache, so
 * issued-and-not-served is the normal outcome, not an edge case. Reading it back
 * is the only way the dashboard can tell the difference — and it costs one
 * handshake to a public hostname, no SSH and no ACME.
 *
 * `rejectUnauthorized: false` is deliberate: an expired, self-signed or
 * wrong-name certificate is exactly the state the customer needs to be told
 * about, and refusing the handshake would throw that information away. Nothing
 * is ever sent over this socket.
 */
function probeServedCertificate(domain: string): Promise<ServedCert> {
  return new Promise((resolve) => {
    let settled = false;
    let socket: ReturnType<typeof tlsConnect> | null = null;
    const done = (r: ServedCert) => {
      if (settled) return;
      settled = true;
      try {
        socket?.destroy();
      } catch {
        /* best effort */
      }
      resolve(r);
    };

    try {
      socket = tlsConnect(
        {
          host: domain,
          port: 443,
          servername: domain,
          rejectUnauthorized: false,
        },
        () => {
          try {
            const peer = socket!.getPeerCertificate();
            if (!peer || !peer.valid_to) {
              return done({ ok: false, reason: "the server presented no certificate" });
            }
            const notAfter = new Date(peer.valid_to);
            if (Number.isNaN(notAfter.getTime())) {
              return done({ ok: false, reason: `its expiry date was unreadable (${peer.valid_to})` });
            }
            const names: string[] = [];
            if (peer.subject?.CN) names.push(String(peer.subject.CN));
            for (const entry of String(peer.subjectaltname ?? "").split(",")) {
              const t = entry.trim();
              if (t.toLowerCase().startsWith("dns:")) names.push(t.slice(4));
            }
            done({ ok: true, notAfter, coversDomain: names.some((n) => hostMatches(n, domain)) });
          } catch (e: any) {
            done({ ok: false, reason: String(e?.message ?? e).slice(0, 140) });
          }
        }
      );
      // Idle timeout covers the connect phase too, so a black-holed host cannot
      // hold the serial worker loop open.
      socket.setTimeout(TLS_PROBE_TIMEOUT_MS, () =>
        done({ ok: false, reason: `port 443 did not respond within ${Math.round(TLS_PROBE_TIMEOUT_MS / 1000)}s` })
      );
      socket.on("error", (e: any) => done({ ok: false, reason: tlsErrorReason(e) }));
    } catch (e: any) {
      done({ ok: false, reason: tlsErrorReason(e) });
    }
  });
}

// Deterministic warning texts. They are compared for equality below so a sweep
// can recognise a note it wrote itself and avoid overwriting a real error.
function notServedWarning(domain: string, reason: string): string {
  return (
    `The certificate exists, but nothing is serving it for https://${domain} — ${reason}. ` +
    `certbot obtains the certificate in standalone mode; it does not install it into your web server. ` +
    `Point your TLS config at /etc/letsencrypt/live/${domain}/fullchain.pem and privkey.pem, then reload it.`
  );
}

function wrongNameWarning(domain: string): string {
  return (
    `Port 443 on ${domain} is serving a certificate issued for a different hostname, so visitors get ` +
    `NET::ERR_CERT_COMMON_NAME_INVALID. Check which certificate your web server is configured to use.`
  );
}

/** Is `s` one of our own probe notes (rather than a real issuance/renewal error)? */
function isProbeWarning(s: string | null): boolean {
  if (!s) return false;
  return s.includes("nothing is serving it for https://") || s.includes("issued for a different hostname");
}

/**
 * Make a row match the certificate the internet can actually see, and return the
 * expiry we now believe (observed if we could read one).
 *
 * This is where "honest status" is enforced: `expiresAt` becomes the observed
 * notAfter, an out-of-band renewal (certbot installs its own systemd timer on the
 * VM, so certificates do renew without us) is picked up instead of triggering a
 * pointless reissue, and an issued-but-not-installed certificate gets a visible
 * note instead of a silent green dot.
 */
async function verifyServed(cert: SslCertificate): Promise<Date | null> {
  const served = await probeServedCertificate(cert.domain);
  const now = Date.now();

  if (served.ok && served.coversDomain) {
    const status = served.notAfter.getTime() > now ? "ACTIVE" : "EXPIRED";
    // A valid certificate on the wire is proof the row is healthy, so any stale
    // renewal error is cleared here rather than nagging forever.
    const lastError =
      status === "ACTIVE"
        ? null
        : `The certificate being served for ${cert.domain} expired on ${served.notAfter
            .toISOString()
            .slice(0, 10)}. Visitors see a browser security warning until a new one is installed.`;
    const changed =
      cert.status !== status ||
      cert.expiresAt?.getTime() !== served.notAfter.getTime() ||
      cert.lastError !== lastError;
    if (changed) {
      await db.sslCertificate.update({
        where: { id: cert.id },
        data: { status, expiresAt: served.notAfter, lastError },
      });
    }
    return served.notAfter;
  }

  // Could not confirm a matching certificate on the wire. Keep the issuer-read
  // expiry (it is still the best observed value we have) but say so — and never
  // clobber a genuine renewal/issuance error with a probe note.
  const note = served.ok ? wrongNameWarning(cert.domain) : notServedWarning(cert.domain, served.reason);
  if ((cert.lastError === null || isProbeWarning(cert.lastError)) && cert.lastError !== note) {
    await db.sslCertificate.update({ where: { id: cert.id }, data: { lastError: note } });
  }
  return cert.expiresAt;
}

// ----------------------------------------------------------------------------
// SSL_ISSUE handler
// ----------------------------------------------------------------------------

type SslPayload = { certId?: string; domain?: string; renewal?: boolean };

function payloadOf(job: { payload: unknown }): SslPayload {
  return (job.payload ?? {}) as SslPayload;
}

export async function sslIssue(job: Job): Promise<void> {
  const payload = payloadOf(job);
  if (!payload.certId) throw new Error("ssl job: missing certId");
  const isRenewal = payload.renewal === true;

  const cert = await db.sslCertificate.findUnique({ where: { id: payload.certId } });
  if (!cert) throw new Error(`SslCertificate ${payload.certId} not found`);

  /** Record the outcome on the job so the rate-limit counter can classify it. */
  const markStep = async (step: string) => {
    await db.job.update({ where: { id: job.id }, data: { step } }).catch(() => {
      /* the outcome marker is an optimisation; never fail the job over it */
    });
  };

  // Mark in-flight so the UI shows "issuing" while we work. On a renewal the row
  // keeps its existing expiresAt, so the dashboard can still say "current
  // certificate valid until <date>" instead of implying the site is down.
  await db.sslCertificate.update({ where: { id: cert.id }, data: { status: "ISSUING" } });

  const phase: IssuePhase = { reachedAcme: false };

  try {
    // ---------------------------------------------------------------------
    // Real issuance path (SSH + certbot). Guarded so it can never run by
    // accident: it happens ONLY when ENABLE_REAL_SSL is explicitly set AND we
    // are not in SANDBOX.
    // ---------------------------------------------------------------------
    const realIssuanceEnabled = !SANDBOX && process.env.ENABLE_REAL_SSL === "1";
    if (realIssuanceEnabled) {
      const { issuedAt, expiresAt } = await issueRealCertificate(cert, phase);

      // Immediately read back what the domain actually serves. certbot
      // --standalone does NOT wire the certificate into nginx/apache, so the
      // common outcome of a successful issue is "obtained but not installed" —
      // telling the customer their site is now HTTPS would be wrong.
      let installNote: string | null = null;
      if (!SANDBOX) {
        const served = await probeServedCertificate(cert.domain);
        if (!served.ok) installNote = notServedWarning(cert.domain, served.reason);
        else if (!served.coversDomain) installNote = wrongNameWarning(cert.domain);
      }

      await db.sslCertificate.update({
        where: { id: cert.id },
        data: { status: "ACTIVE", issuedAt, expiresAt, lastError: installNote },
      });
      await markStep(SSL_STEP_ISSUED);
      await notify(
        cert.userId,
        `SSL certificate ${isRenewal ? "renewed" : "issued"} for ${cert.domain}`,
        installNote
          ? `Obtained, valid until ${expiresAt.toISOString().slice(0, 10)} — but not yet installed in your web server.`
          : `Verified live on https://${cert.domain}, valid until ${expiresAt.toISOString().slice(0, 10)}.`,
        "/dashboard/ssl"
      );
      return;
    }

    // Simulation is a SANDBOX affordance and MUST NEVER run in production.
    //
    // Until 2026-07-25 it did: production has no ENABLE_REAL_SSL, so every real
    // customer request fell through to the block below, which wrote status
    // "ACTIVE" with an invented 90-day expiry and told them "your Let's Encrypt
    // certificate is active" — while no certbot had run and no certificate
    // existed. Identical in kind to the migration reporting "Sites serving: 4/4"
    // with six domains dark: the system asserting an outcome it never verified.
    //
    // A certificate we did not issue is a FAILURE, and it must say so loudly
    // enough that an operator notices the flag is missing.
    if (!SANDBOX) {
      throw new Error(
        "Certificate issuance is switched off on this server (ENABLE_REAL_SSL is not set), " +
          "so no certificate was requested from Let's Encrypt. Nothing was installed — " +
          "this certificate is NOT active. Ask support to enable real issuance."
      );
    }

    // Default: simulated success (SANDBOX-only, no SSH, no certbot).
    const now = new Date();
    await db.sslCertificate.update({
      where: { id: cert.id },
      data: {
        status: "ACTIVE",
        issuedAt: now,
        expiresAt: new Date(now.getTime() + SANDBOX_CERT_LIFETIME_MS),
        lastError: null,
      },
    });
    await markStep(SSL_STEP_SANDBOX);
    await notify(
      cert.userId,
      `SSL certificate ${isRenewal ? "renewed" : "issued"} for ${cert.domain}`,
      "Your Let's Encrypt certificate is active and valid for 90 days (sandbox).",
      "/dashboard/ssl"
    );
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 500);

    // A failed RENEWAL must not erase the fact that the current certificate is
    // still serving traffic. Flipping a cert with 20 valid days left to FAILED
    // is its own kind of lie — and it would panic a customer whose site is fine.
    let status: string;
    if (isRenewal && cert.expiresAt && cert.expiresAt.getTime() > Date.now()) {
      status = "ACTIVE";
    } else if (isRenewal && cert.issuedAt) {
      // Was genuinely issued once, so the honest end state is expired, not "failed".
      status = "EXPIRED";
    } else {
      status = "FAILED";
    }

    const detail = isRenewal ? `Renewal failed: ${reason}`.slice(0, 500) : reason;
    await db.sslCertificate.update({
      where: { id: cert.id },
      data: { status, lastError: detail },
    });
    await markStep(phase.reachedAcme ? SSL_STEP_ACME_FAILED : SSL_STEP_PREFLIGHT_FAILED);
    await notify(
      cert.userId,
      `SSL certificate ${isRenewal ? "renewal" : "request"} failed for ${cert.domain}`,
      detail.slice(0, 200),
      "/dashboard/ssl"
    );
  }
}

// ----------------------------------------------------------------------------
// Lifecycle sweep: reconcile stalled/expired rows, then renew what is due.
// ----------------------------------------------------------------------------

type Attempt = { attempts: number; lastAt: Date };

/**
 * Whether an SSL_ISSUE attempt should be counted against the Let's Encrypt
 * weekly limit. Attempts that died locally (no certbot, port 80 busy, SSH
 * refused) never reached the ACME server and must NOT count — otherwise a
 * customer with a busy port 80 gets locked out of certificates for a week by
 * failures Let's Encrypt never saw. `null` (in flight, or a legacy row) counts:
 * when in doubt, protect the limit.
 */
function attemptCountsAgainstLimit(step: string | null): boolean {
  return step !== SSL_STEP_PREFLIGHT_FAILED && step !== SSL_STEP_SANDBOX;
}

/**
 * Issue attempts in the current window, keyed by DOMAIN — not by certificate id.
 *
 * The key matters: Let's Encrypt's duplicate-certificate limit is per identical
 * hostname set, and deleting a row and requesting it again mints a fresh certId.
 * A per-certId counter would therefore reset on every delete/re-request, letting
 * a frustrated customer burn all five weekly slots in minutes and lose HTTPS for
 * a week.
 */
async function loadIssueHistory(): Promise<Map<string, Attempt>> {
  const since = new Date(Date.now() - ISSUE_WINDOW_MS);
  const jobs = await db.job.findMany({
    where: { type: "SSL_ISSUE", createdAt: { gt: since } },
    select: { payload: true, step: true, createdAt: true },
    orderBy: { createdAt: "asc" },
  });
  const map = new Map<string, Attempt>();
  for (const j of jobs) {
    const domain = payloadOf(j).domain;
    if (!domain) continue; // pre-2026-07-26 jobs carried only certId
    if (!attemptCountsAgainstLimit(j.step)) continue;
    const prev = map.get(domain);
    map.set(domain, { attempts: (prev?.attempts ?? 0) + 1, lastAt: j.createdAt });
  }
  return map;
}

/** Live (queued or running) SSL_ISSUE jobs, indexed by the cert they belong to. */
async function loadLiveIssueJobs() {
  const jobs = await db.job.findMany({
    where: { type: "SSL_ISSUE", status: { in: ["QUEUED", "RUNNING"] } },
    select: { id: true, status: true, createdAt: true, payload: true },
    orderBy: { createdAt: "asc" },
  });
  const byCert = new Map<string, (typeof jobs)[number]>();
  for (const j of jobs) {
    const certId = payloadOf(j).certId;
    if (certId && !byCert.has(certId)) byCert.set(certId, j);
  }
  return byCert;
}

/**
 * Age out rows that can no longer make progress, and write EXPIRED.
 *
 * Two real failures this prevents:
 *  - the worker is restarted mid-issue, `reapStuckJobs` retires the job, and the
 *    certificate row sits in ISSUING forever. The customer could not even delete
 *    it (lib/actions-ssl.ts refused to delete an ISSUING row), so the domain was
 *    permanently unrequestable — requestCertificate rejects duplicates while a
 *    PENDING/ISSUING/ACTIVE row exists.
 *  - a certificate passes its expiry and keeps a green pulsing ACTIVE dot while
 *    every visitor gets NET::ERR_CERT_DATE_INVALID. EXPIRED was documented in the
 *    schema and written by nothing.
 */
export async function sslReconcileSweep(): Promise<void> {
  const now = Date.now();

  const inflight = await db.sslCertificate.findMany({
    where: { status: { in: ["PENDING", "ISSUING"] } },
    take: MAX_CERTS_PER_SWEEP,
  });

  if (inflight.length > 0) {
    const live = await loadLiveIssueJobs();
    const terminal = await db.job.findMany({
      where: {
        type: "SSL_ISSUE",
        status: { in: ["DONE", "FAILED"] },
        createdAt: { gt: new Date(now - ISSUE_WINDOW_MS) },
      },
      select: { status: true, error: true, updatedAt: true, payload: true },
      orderBy: { createdAt: "desc" },
    });

    let cleared = 0;
    for (const cert of inflight) {
      // A row attached to a queued/running job is NOT stalled, however long it
      // has waited: the worker is a single serial queue platform-wide, so a
      // legitimate wait behind a MIGRATE can be tens of minutes. The dashboard
      // explains that wait instead (see the queue position on /dashboard/ssl).
      if (live.has(cert.id)) continue;

      const last = terminal.find((j) => payloadOf(j).certId === cert.id);
      const ageMs = now - cert.createdAt.getTime();
      let reason: string | null = null;

      if (last?.status === "FAILED" && now - last.updatedAt.getTime() > ORPHAN_GRACE_MS) {
        reason =
          `Issuance stopped before it finished — the worker job failed terminally` +
          `${last.error ? `: ${last.error.slice(0, 200)}` : " (no error recorded)"}. ` +
          `No certificate was installed, so this is not active. You can delete this row and request it again.`;
      } else if (last?.status === "DONE" && now - last.updatedAt.getTime() > ORPHAN_GRACE_MS) {
        reason =
          `Issuance ended without recording a result — the worker was interrupted after the certbot step. ` +
          `We cannot confirm a certificate exists, so this is not being reported as active. Request it again.`;
      } else if (!last && ageMs > ORPHAN_PENDING_MS) {
        reason =
          `No issuance job ever ran for this request — it was queued ${Math.round(ageMs / 60_000)} minutes ago ` +
          `and never picked up. Nothing was installed. Request it again.`;
      }

      if (!reason) continue;
      await db.sslCertificate.update({
        where: { id: cert.id },
        data: { status: "FAILED", lastError: reason.slice(0, 500) },
      });
      await notifyOnce(
        cert.userId,
        `SSL certificate request for ${cert.domain} did not complete`,
        reason.slice(0, 200),
        6 * 3600_000
      );
      cleared++;
    }
    if (cleared > 0) console.log(`[ssl] reconciled ${cleared} stalled certificate row(s)`);
  }

  // Anything still flagged ACTIVE past its observed expiry is not active.
  const lapsed = await db.sslCertificate.findMany({
    where: { status: "ACTIVE", expiresAt: { lt: new Date(now) } },
    take: MAX_CERTS_PER_SWEEP,
  });
  for (const cert of lapsed) {
    await db.sslCertificate.update({ where: { id: cert.id }, data: { status: "EXPIRED" } });
    await notifyOnce(
      cert.userId,
      `SSL certificate expired for ${cert.domain}`,
      `The certificate expired on ${cert.expiresAt!.toISOString().slice(0, 10)}. Visitors now see a browser ` +
        `security warning on https://${cert.domain} until a new one is issued and installed.`,
      24 * 3600_000
    );
  }
  if (lapsed.length > 0) console.log(`[ssl] marked ${lapsed.length} certificate(s) EXPIRED`);
}

/**
 * Reissue certificates before they die.
 *
 * There was no renewal of any kind before 2026-07-26: `SslCertificate.autoRenew`
 * was written by the dashboard switch and read only for display, so every
 * certificate the platform ever issued expired silently at 90 days.
 *
 * The order of operations here is deliberate — verify what is actually served
 * BEFORE deciding to reissue. certbot installs its own systemd renewal timer on
 * the customer's VM, so certificates frequently renew without us; reissuing on a
 * stale `expiresAt` would spend Let's Encrypt slots on work already done.
 */
export async function sslRenewalSweep(): Promise<void> {
  const now = Date.now();
  const dueBefore = new Date(now + RENEW_LEAD_MS);

  const candidates = await db.sslCertificate.findMany({
    where: {
      OR: [
        { status: "ACTIVE", expiresAt: { lt: dueBefore } },
        // No observed expiry at all: we cannot prove this is valid, so treat it
        // as needing verification/reissue (still subject to every cap below).
        { status: "ACTIVE", expiresAt: null },
        { status: "EXPIRED" },
      ],
    },
    orderBy: [{ expiresAt: "asc" }],
    take: MAX_CERTS_PER_SWEEP,
  });
  if (candidates.length === 0) return;

  const live = await loadLiveIssueJobs();
  const history = await loadIssueHistory();
  const probeDeadline = now + PROBE_BUDGET_MS;
  let enqueued = 0;

  for (const cert of candidates) {
    // Never stack a second issue job on a certificate already being worked.
    if (live.has(cert.id)) continue;

    let expiresAt = cert.expiresAt;
    let fresh = cert;
    if (!SANDBOX && Date.now() < probeDeadline) {
      // Sandbox domains are fictional, so the probe would only ever produce a
      // scary "nothing is serving this" note there.
      expiresAt = await verifyServed(cert);
      const reloaded = await db.sslCertificate.findUnique({ where: { id: cert.id } });
      if (!reloaded) continue;
      fresh = reloaded;
    }

    // Re-evaluate against the observed expiry, not the one we started with.
    const due = !expiresAt || expiresAt.getTime() - Date.now() <= RENEW_LEAD_MS;
    if (!due) continue;

    if (!fresh.autoRenew) {
      // The switch is no longer decoration: off means we really do nothing, so
      // the customer has to be told before the site breaks.
      const when = expiresAt ? expiresAt.toISOString().slice(0, 10) : "an unknown date";
      await notifyOnce(
        fresh.userId,
        `SSL certificate for ${fresh.domain} needs renewing`,
        `Auto-renew is switched off for this certificate. It expires on ${when} and will not be replaced ` +
          `automatically — turn auto-renew on, or renew it yourself, before then.`,
        3 * 86400_000
      );
      continue;
    }

    const hist = history.get(fresh.domain);
    const attempts = hist?.attempts ?? 0;

    if (attempts >= MAX_ISSUE_ATTEMPTS_PER_WINDOW) {
      // Stop, loudly, one slot short of Let's Encrypt's weekly limit.
      const resumesAt = new Date((hist?.lastAt.getTime() ?? now) + ISSUE_WINDOW_MS);
      const note =
        `${RENEWAL_PAUSED_PREFIX} until ${resumesAt.toISOString().slice(0, 16).replace("T", " ")} UTC: ` +
        `${attempts} certificate requests for ${fresh.domain} have already been made in the last 7 days. ` +
        `Let's Encrypt allows only 5 identical certificates per week, so we stop short of the limit rather ` +
        `than lock you out of HTTPS entirely. Fix the cause of the failures, then renewal resumes on its own.` +
        (fresh.lastError && !fresh.lastError.startsWith(RENEWAL_PAUSED_PREFIX)
          ? ` Last error: ${fresh.lastError.slice(0, 160)}`
          : "");
      if (fresh.lastError !== note) {
        await db.sslCertificate.update({
          where: { id: fresh.id },
          data: { lastError: note.slice(0, 500) },
        });
      }
      await notifyOnce(
        fresh.userId,
        `SSL renewal paused for ${fresh.domain}`,
        note.slice(0, 200),
        3 * 86400_000
      );
      continue;
    }

    // Escalating backoff. With RENEW_BACKOFF_MS the sweep cannot produce more
    // than four certbot runs per hostname per week no matter how often it runs.
    const wait = RENEW_BACKOFF_MS[Math.min(attempts, RENEW_BACKOFF_MS.length - 1)];
    if (hist && Date.now() - hist.lastAt.getTime() < wait) continue;

    // Respect the platform's one-in-flight-job-per-server invariant (same as
    // scheduledBackupSweep) so a renewal never queues behind its own siblings.
    if (fresh.serverId) {
      const busy = await db.job.count({
        where: { serverId: fresh.serverId, status: { in: ["QUEUED", "RUNNING"] } },
      });
      if (busy > 0) continue;
    }

    await db.job.create({
      data: {
        type: "SSL_ISSUE",
        serverId: fresh.serverId,
        // `domain` is what the rate-limit counter keys on; `renewal` tells the
        // handler to keep a still-valid certificate ACTIVE if the reissue fails.
        payload: { certId: fresh.id, domain: fresh.domain, renewal: true },
      },
    });
    // Count it locally too, so two rows for the same hostname in one pass cannot
    // both enqueue.
    history.set(fresh.domain, { attempts: attempts + 1, lastAt: new Date() });
    enqueued++;
  }

  if (enqueued > 0) console.log(`[ssl] renewal sweep enqueued ${enqueued} reissue job(s)`);
}

/**
 * One entry point for the worker loop: reconcile first (so an expired row is
 * EXPIRED before we consider it), then renew what is due.
 */
export async function sslSweep(): Promise<void> {
  await sslReconcileSweep();
  await sslRenewalSweep();
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import type { SslCertificate } from "@prisma/client";

/**
 * Customer SSL certificate management — one-click Let's Encrypt certs for a
 * domain the customer has already pointed at their server. Ordering is
 * ownership-checked here (at enqueue time); the actual issue runs in the worker
 * (worker/ssl.ts, SSL_ISSUE) which SSHes to the box and runs certbot — or, in
 * SANDBOX/staging, simulates a successful issue. worker/ssl.ts's `sslSweep` then
 * owns renewal and reconciliation.
 */

// Basic FQDN: one or more dot-separated labels + a 2–24 char alpha TLD. Rejects
// wildcards, protocols, ports and paths — certbot wants a bare hostname.
const FQDN_RE =
  /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;

/**
 * Let's Encrypt rate-limit guard. MUST stay in sync with worker/ssl.ts — this
 * module cannot import it (worker/ssl.ts pulls in ssh2, which must never reach
 * the Next bundle), so the four values are duplicated deliberately.
 *
 * LE allows 5 duplicate certificates (identical hostname set) per week; blowing
 * through it locks the customer out of HTTPS for a full week. We cap every
 * source of attempts — this file's manual request/renew and the worker's
 * automatic renewal sweep — at 4 per hostname per rolling week, sharing one
 * counter so they cannot add up to more than the limit between them.
 */
const ISSUE_WINDOW_MS = 7 * 86400_000;
const MAX_ISSUE_ATTEMPTS_PER_WINDOW = 4;
/** Outcomes that never reached the ACME server, so never consumed a slot. */
const SSL_STEP_PREFLIGHT_FAILED = "failed before contacting Let's Encrypt";
const SSL_STEP_SANDBOX = "simulated (sandbox)";

type SslPayload = { certId?: string; domain?: string; renewal?: boolean };

function payloadOf(job: { payload: unknown }): SslPayload {
  return (job.payload ?? {}) as SslPayload;
}

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function ownedCertificate(id: string) {
  const user = await requireUser();
  const cert = await db.sslCertificate.findUnique({ where: { id } });
  if (!cert) throw new Error("Not found");
  if (cert.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, cert };
}

/**
 * Issue attempts against `domain` inside the current rate-limit window.
 *
 * Keyed on the hostname, not the certificate id: LE's duplicate-certificate
 * limit is per identical hostname set, and deleting a row and requesting it
 * again mints a fresh certId. A per-row counter would reset on every
 * delete/re-request, which is exactly how a customer chasing a broken
 * certificate could burn all five weekly slots in a couple of minutes.
 */
async function issueAttemptsFor(
  domain: string
): Promise<{ attempts: number; resumesAt: Date | null }> {
  const since = new Date(Date.now() - ISSUE_WINDOW_MS);
  const jobs = await db.job.findMany({
    where: { type: "SSL_ISSUE", createdAt: { gt: since } },
    select: { payload: true, step: true, createdAt: true },
    orderBy: { createdAt: "asc" },
  });
  let attempts = 0;
  let oldest: Date | null = null;
  for (const j of jobs) {
    if (payloadOf(j).domain !== domain) continue;
    // `step === null` means in flight (or a pre-2026-07-26 job): count it. When
    // in doubt we protect the limit rather than the convenience.
    if (j.step === SSL_STEP_PREFLIGHT_FAILED || j.step === SSL_STEP_SANDBOX) continue;
    attempts++;
    if (!oldest) oldest = j.createdAt;
  }
  return {
    attempts,
    resumesAt: oldest ? new Date(oldest.getTime() + ISSUE_WINDOW_MS) : null,
  };
}

function rateLimitMessage(domain: string, resumesAt: Date | null): string {
  const when = resumesAt
    ? `${resumesAt.toISOString().slice(0, 16).replace("T", " ")} UTC`
    : "later this week";
  return (
    `${MAX_ISSUE_ATTEMPTS_PER_WINDOW} certificate requests for ${domain} have already been made in the ` +
    `last 7 days. Let's Encrypt allows only 5 identical certificates per week, and going over would block ` +
    `new certificates for this domain for a full week — so we stop one short. You can try again after ${when}.`
  );
}

/** Live (queued or running) SSL_ISSUE job for a certificate, if any. */
async function liveIssueJob(certId: string) {
  const jobs = await db.job.findMany({
    where: { type: "SSL_ISSUE", status: { in: ["QUEUED", "RUNNING"] } },
    select: { id: true, status: true, createdAt: true, payload: true },
    orderBy: { createdAt: "asc" },
  });
  return jobs.find((j) => payloadOf(j).certId === certId) ?? null;
}

/** All of the current user's SSL certificates, newest first. */
export async function listCertificates(): Promise<SslCertificate[]> {
  const user = await requireUser();
  return db.sslCertificate.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
  });
}

/**
 * Request a one-click Let's Encrypt certificate for `domain` on one of the
 * caller's servers. Validates the domain, checks server ownership, applies the
 * shared rate-limit guard, creates a PENDING SslCertificate row and enqueues an
 * SSL_ISSUE job.
 */
export async function requestCertificate(
  serverId: string,
  domain: string
): Promise<{ error?: string; id?: string }> {
  let ctx;
  try {
    ctx = await ownedServer(serverId);
  } catch (e: any) {
    return { error: e.message };
  }
  const { user, server } = ctx;

  const clean = String(domain ?? "").toLowerCase().trim().replace(/\.$/, "");
  if (!FQDN_RE.test(clean)) {
    return { error: "Enter a valid domain name (e.g. app.example.com) — no protocol, port or wildcard." };
  }

  // One active/in-flight cert per (user, domain): don't let a customer stack
  // duplicate issue jobs for the same hostname.
  const existing = await db.sslCertificate.findFirst({
    where: { userId: user.id, domain: clean, status: { in: ["PENDING", "ISSUING", "ACTIVE"] } },
  });
  if (existing) {
    return {
      error:
        existing.status === "ACTIVE"
          ? `You already have an active certificate for ${clean}.`
          : `A certificate for ${clean} is already being issued.`,
    };
  }

  // The duplicate check above is defeated by delete-and-retry, so the weekly
  // rate-limit guard is the thing that actually stops a retry loop from burning
  // Let's Encrypt's limit.
  const rate = await issueAttemptsFor(clean);
  if (rate.attempts >= MAX_ISSUE_ATTEMPTS_PER_WINDOW) {
    return { error: rateLimitMessage(clean, rate.resumesAt) };
  }

  const cert = await db.sslCertificate.create({
    data: {
      userId: user.id,
      serverId: server.id,
      domain: clean,
      status: "PENDING",
      issuer: "letsencrypt",
    },
  });
  await db.job.create({
    // `domain` is carried in the payload because the rate-limit counter above
    // keys on the hostname and must survive the certificate row being deleted.
    data: { type: "SSL_ISSUE", serverId: server.id, payload: { certId: cert.id, domain: clean } },
  });
  await db.auditLog.create({
    data: { userId: user.id, action: "ssl.request", detail: `${clean} on ${server.hostname}` },
  });
  revalidatePath("/dashboard/ssl");
  return { id: cert.id };
}

/**
 * Reissue a certificate now (owner only), for an ACTIVE/EXPIRED/FAILED row.
 *
 * Shares the weekly counter with requestCertificate and the worker's renewal
 * sweep, so a customer hammering this button cannot exhaust Let's Encrypt's
 * duplicate-certificate limit.
 */
export async function renewCertificate(id: string): Promise<{ error?: string }> {
  let ctx;
  try {
    ctx = await ownedCertificate(id);
  } catch (e: any) {
    return { error: e.message };
  }
  const { user, cert } = ctx;

  if (!["ACTIVE", "EXPIRED", "FAILED"].includes(cert.status)) {
    return { error: "This certificate is already being worked on — wait for the current attempt to finish." };
  }
  if (!cert.serverId) {
    return { error: "This certificate is not attached to a server, so it cannot be issued." };
  }
  if (await liveIssueJob(cert.id)) {
    return { error: "An issue job for this certificate is already queued." };
  }

  const rate = await issueAttemptsFor(cert.domain);
  if (rate.attempts >= MAX_ISSUE_ATTEMPTS_PER_WINDOW) {
    return { error: rateLimitMessage(cert.domain, rate.resumesAt) };
  }

  // One in-flight job per server, matching the worker's own invariant.
  const busy = await db.job.count({
    where: { serverId: cert.serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (busy > 0) {
    return {
      error:
        "Another operation is already queued for this server. The platform runs one job at a time — try again once it finishes.",
    };
  }

  await db.job.create({
    data: {
      type: "SSL_ISSUE",
      serverId: cert.serverId,
      // `renewal: true` keeps a still-valid certificate ACTIVE if the reissue
      // fails, instead of flipping a working site's row to FAILED.
      payload: { certId: cert.id, domain: cert.domain, renewal: true },
    },
  });
  await db.auditLog.create({
    data: { userId: user.id, action: "ssl.renew", detail: `${cert.domain}` },
  });
  revalidatePath("/dashboard/ssl");
  return {};
}

/**
 * Permanently remove a certificate record (owner only).
 *
 * ISSUING is only protected while a job is genuinely running. Before
 * 2026-07-26 this refused every ISSUING row unconditionally, so a row stranded
 * by a worker restart was permanently undeletable — and because
 * requestCertificate rejects a new request while a PENDING/ISSUING/ACTIVE row
 * exists for the hostname, the customer lost the ability to get a certificate
 * for that domain at all, with no way to clear it themselves.
 */
export async function deleteCertificate(id: string): Promise<{ error?: string }> {
  let ctx;
  try {
    ctx = await ownedCertificate(id);
  } catch (e: any) {
    return { error: e.message };
  }
  const { user, cert } = ctx;

  if (cert.status === "PENDING" || cert.status === "ISSUING") {
    const live = await liveIssueJob(cert.id);
    if (live?.status === "RUNNING") {
      return {
        error:
          "certbot is running for this domain right now — deleting mid-issue would leave a certificate on the " +
          "server with no record of it. Try again in a minute.",
      };
    }
    if (live) {
      // Queued but not started: cancel it, otherwise the worker would pick up a
      // job whose certificate row no longer exists and log a spurious failure.
      await db.job.updateMany({
        where: { id: live.id, status: "QUEUED" },
        data: {
          status: "FAILED",
          error: "Cancelled — the customer deleted the certificate request before it started.",
        },
      });
    }
  }

  await db.sslCertificate.delete({ where: { id } });
  await db.auditLog.create({
    data: { userId: user.id, action: "ssl.delete", detail: `${cert.domain}` },
  });
  revalidatePath("/dashboard/ssl");
  return {};
}

/**
 * Flip automatic renewal on/off for a certificate (owner only).
 *
 * This is no longer decoration: worker/ssl.ts's renewal sweep reads `autoRenew`
 * and, when it is off, reissues nothing and warns the customer before expiry
 * instead.
 */
export async function toggleAutoRenew(id: string): Promise<{ error?: string }> {
  let ctx;
  try {
    ctx = await ownedCertificate(id);
  } catch (e: any) {
    return { error: e.message };
  }
  await db.sslCertificate.update({
    where: { id },
    data: { autoRenew: !ctx.cert.autoRenew },
  });
  await db.auditLog.create({
    data: {
      userId: ctx.user.id,
      action: "ssl.autorenew",
      detail: `${ctx.cert.domain} -> ${!ctx.cert.autoRenew ? "on" : "off"}`,
    },
  });
  revalidatePath("/dashboard/ssl");
  return {};
}

"use client";

import { useState, useTransition } from "react";
import { Badge, StatusDot } from "@/components/ui/primitives";
import {
  requestCertificate,
  renewCertificate,
  deleteCertificate,
  toggleAutoRenew,
} from "@/lib/actions-ssl";

/**
 * SSL certificate manager for /dashboard/ssl.
 *
 * Replaces SslManager, whose table could not tell the truth about a certificate:
 * it rendered `expiresAt` as a bare date with no notion of whether that date had
 * passed (an expired cert kept a green pulsing ACTIVE dot while every visitor got
 * NET::ERR_CERT_DATE_INVALID), showed a mid-issuance row as the grey STOPPED dot,
 * gave a queued request no explanation at all — one sat "pending" for 13 minutes
 * behind another tenant's MIGRATE with nothing on screen to say so — and hard-
 * disabled Delete on any ISSUING row, stranding rows a worker restart had
 * orphaned.
 *
 * Every status here is derived from an observed value: `expiresAt` is the
 * notAfter read off the certificate (by openssl on the box at issuance, then by a
 * TLS read-back of :443 in the renewal sweep), and `lastError` on a non-FAILED
 * row means "the certificate exists but something about it is wrong" — most often
 * that certbot obtained it in standalone mode and nothing installed it.
 */

/** Where a still-unfinished request sits in the platform's single serial queue. */
export type QueueInfo = {
  /** running = certbot is executing; queued = waiting its turn; none = no job at all. */
  state: "running" | "queued" | "none";
  /** 1 = next to run. Only meaningful when state === "queued". */
  position: number;
  aheadCount: number;
  queuedAtIso: string;
  /** The job holding the worker right now, if any. */
  blocking: { type: string; mine: boolean } | null;
};

export type CertRow = {
  id: string;
  domain: string;
  status: string;
  issuer: string;
  autoRenew: boolean;
  serverName: string | null;
  issuedAt: string | null;
  /** The observed notAfter. Never a computed guess — null means "not verified". */
  expiresAt: string | null;
  lastError: string | null;
  queue: QueueInfo | null;
};

export type ServerOption = { id: string; hostname: string };

const DAY_MS = 86_400_000;

function fmtDate(iso: string | null): string {
  return iso ? new Date(iso).toISOString().slice(0, 10) : "—";
}

function daysUntil(iso: string | null): number | null {
  if (!iso) return null;
  return Math.floor((new Date(iso).getTime() - Date.now()) / DAY_MS);
}

function ago(iso: string): string {
  const mins = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 60_000));
  if (mins < 1) return "just now";
  if (mins === 1) return "1 minute ago";
  if (mins < 60) return `${mins} minutes ago`;
  const hrs = Math.round(mins / 60);
  return hrs === 1 ? "1 hour ago" : `${hrs} hours ago`;
}

// Job types the SSL request can be stuck behind. The platform worker is a single
// serial queue, so anything here can hold up a certificate.
const JOB_LABELS: Record<string, string> = {
  MIGRATE: "server migration",
  PROVISION: "server build",
  REINSTALL: "OS reinstall",
  RESIZE: "server resize",
  DISK_EXPAND: "disk expansion",
  BACKUP_CREATE: "backup",
  BACKUP_RESTORE: "backup restore",
  SNAPSHOT_CREATE: "snapshot",
  SNAPSHOT_ROLLBACK: "snapshot rollback",
  SSL_ISSUE: "certificate request",
  WEBSITE_SSL: "website SSL setup",
  GAME_UPDATE: "game server update",
  APP_INSTALL: "app install",
};

function jobLabel(type: string): string {
  return JOB_LABELS[type] ?? type.toLowerCase().replace(/_/g, " ");
}

// ---------------------------------------------------------------------------
// Request form
// ---------------------------------------------------------------------------

function RequestCertificate({ servers }: { servers: ServerOption[] }) {
  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
  const [domain, setDomain] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const noServers = servers.length === 0;

  return (
    <div className="card p-5">
      <h3 className="text-base font-semibold">Request a certificate</h3>
      <p className="mt-1 text-sm text-slate-400">
        Point your domain&apos;s DNS at the server first and leave port 80 free — issuance uses the
        HTTP-01 challenge. Requests run in the platform queue, so a busy queue can delay one by
        several minutes.
      </p>
      <div className="mt-4 flex flex-wrap items-end gap-3">
        <div>
          <label className="label">Server</label>
          <select
            className="input w-52"
            value={serverId}
            onChange={(e) => setServerId(e.target.value)}
            disabled={pending || noServers}
          >
            {noServers ? (
              <option value="">No running servers</option>
            ) : (
              servers.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.hostname}
                </option>
              ))
            )}
          </select>
        </div>
        <div>
          <label className="label">Domain</label>
          <input
            className="input w-64"
            value={domain}
            onChange={(e) => setDomain(e.target.value)}
            placeholder="app.example.com"
            disabled={pending || noServers}
          />
        </div>
        <button
          className="btn-primary"
          disabled={pending || noServers || !serverId || domain.trim().length < 3}
          onClick={() =>
            start(async () => {
              setError(null);
              const res = await requestCertificate(serverId, domain.trim());
              if (res?.error) setError(res.error);
              else setDomain("");
            })
          }
        >
          {pending ? "Requesting…" : "Request certificate"}
        </button>
      </div>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      {noServers && (
        <p className="mt-2 text-xs text-slate-500">
          You need a running server before you can request a certificate.
        </p>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Honest status + queue explanation
// ---------------------------------------------------------------------------

/**
 * Why this exists: "pending" with a spinner is indistinguishable from "broken".
 * The worker claims one QUEUED job at a time platform-wide, ordered by creation,
 * so a certificate really can wait behind another customer's long migration.
 * Saying so — with a position and how long it has waited — is the difference
 * between a wait and an outage.
 */
function QueueNote({ q }: { q: QueueInfo | null }) {
  if (!q) return null;

  if (q.state === "none") {
    return (
      <p className="mt-1 text-xs text-amber-400">
        No worker job is attached to this request, so nothing is running. It is cleared automatically
        within 15 minutes — or delete it and try again now.
      </p>
    );
  }

  if (q.state === "running") {
    return (
      <p className="mt-1 text-xs text-slate-400">
        certbot is running on your server now — started {ago(q.queuedAtIso)}.
      </p>
    );
  }

  const blocking = q.blocking
    ? `${q.blocking.mine ? "your" : "another customer's"} ${jobLabel(q.blocking.type)}`
    : "the job currently running";

  return (
    <p className="mt-1 text-xs text-slate-400">
      Waiting for other work to finish —{" "}
      {q.aheadCount === 0 ? "next in line" : `position ${q.position} in the platform queue`}. Jobs run
      one at a time and {blocking} is ahead of it. Queued {ago(q.queuedAtIso)}. Nothing is wrong.
    </p>
  );
}

function StatusCell({ c }: { c: CertRow }) {
  const left = daysUntil(c.expiresAt);

  if (c.status === "PENDING") {
    return (
      <div>
        <StatusDot status="QUEUED" label={c.queue?.state === "none" ? "not started" : "queued"} />
        <QueueNote q={c.queue} />
      </div>
    );
  }

  if (c.status === "ISSUING") {
    return (
      <div>
        {/* PROVISIONING, not ISSUING: `statusColors` has no ISSUING entry, so the
            literal status falls back to STOPPED's neutral grey and a certificate
            mid-issuance reads as "nothing happening". */}
        <StatusDot status="PROVISIONING" label="issuing" />
        {left !== null && left >= 0 && (
          <p className="mt-1 text-xs text-slate-400">
            Renewing. Your current certificate stays valid for {left} more day{left === 1 ? "" : "s"}.
          </p>
        )}
        <QueueNote q={c.queue} />
      </div>
    );
  }

  if (c.status === "EXPIRED") {
    return (
      <div>
        <StatusDot status="FAILED" label="expired" />
        <p className="mt-1 text-xs text-red-400">
          {left !== null
            ? `Expired ${Math.abs(left)} day${Math.abs(left) === 1 ? "" : "s"} ago — visitors see a browser security warning.`
            : "Visitors see a browser security warning until a new certificate is installed."}
        </p>
      </div>
    );
  }

  if (c.status === "ACTIVE") {
    // Never a plain green dot unless we have a real observed expiry in the future
    // and nothing has flagged a problem with the certificate.
    if (c.expiresAt === null) {
      return (
        <div>
          <StatusDot status="PENDING" label="unverified" />
          <p className="mt-1 text-xs text-amber-400">
            No expiry date has been read back from this certificate, so we cannot confirm it is valid.
          </p>
        </div>
      );
    }
    if (c.lastError) {
      return (
        <div>
          {/* Amber on purpose: the certificate exists, but the site is not
              necessarily serving it. Green here is the lie this page fixes. */}
          <StatusDot status="COMPLETED_WITH_ISSUES" label="issued — needs attention" />
        </div>
      );
    }
    return (
      <div className="flex flex-wrap items-center gap-2">
        <StatusDot status="ACTIVE" label="active" />
        {left !== null && (
          <Badge tone={left <= 7 ? "red" : left <= 21 ? "amber" : "green"}>
            {left} day{left === 1 ? "" : "s"} left
          </Badge>
        )}
      </div>
    );
  }

  // FAILED (and anything unrecognised).
  return <StatusDot status={c.status} />;
}

// ---------------------------------------------------------------------------
// Row actions
// ---------------------------------------------------------------------------

function CertActions({ cert }: { cert: CertRow }) {
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const run = (fn: () => Promise<{ error?: string }>, confirmMsg?: string) => {
    if (confirmMsg && !window.confirm(confirmMsg)) return;
    start(async () => {
      setError(null);
      const res = await fn();
      if (res?.error) setError(res.error);
    });
  };

  // Only a genuinely executing certbot run blocks deletion. A row stranded in
  // ISSUING by a dead worker must be clearable, or the customer can never
  // request that domain again.
  const issuingNow = cert.status === "ISSUING" && cert.queue?.state === "running";
  const canRenew = ["ACTIVE", "EXPIRED", "FAILED"].includes(cert.status);

  return (
    <div className="flex flex-col items-end gap-1.5">
      <div className="flex items-center gap-2">
        <button
          type="button"
          role="switch"
          aria-checked={cert.autoRenew}
          aria-label="Toggle auto-renew"
          disabled={pending}
          onClick={() => run(() => toggleAutoRenew(cert.id))}
          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
            cert.autoRenew ? "bg-brand-500" : "bg-white/15"
          } ${pending ? "opacity-60" : ""}`}
        >
          <span
            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
              cert.autoRenew ? "translate-x-5" : "translate-x-0.5"
            }`}
          />
        </button>
        {canRenew && (
          <button
            className="btn-ghost px-3 py-1 text-xs"
            disabled={pending}
            onClick={() =>
              run(
                () => renewCertificate(cert.id),
                `Reissue the certificate for "${cert.domain}" now? Let's Encrypt allows only 5 identical ` +
                  `certificates per week, so use this sparingly.`
              )
            }
          >
            Renew now
          </button>
        )}
        <button
          className="btn-danger px-3 py-1 text-xs"
          disabled={pending || issuingNow}
          title={issuingNow ? "certbot is running for this domain right now" : undefined}
          onClick={() =>
            run(
              () => deleteCertificate(cert.id),
              `Delete the certificate for "${cert.domain}"? This removes it from your account.`
            )
          }
        >
          Delete
        </button>
      </div>
      {!cert.autoRenew && (
        <span className="text-xs text-slate-500">
          Auto-renew off — this will not be replaced before it expires.
        </span>
      )}
      {error && <span className="max-w-md text-right text-xs text-red-400">{error}</span>}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Full manager
// ---------------------------------------------------------------------------

export function SslCertificates({
  certificates,
  servers,
}: {
  certificates: CertRow[];
  servers: ServerOption[];
}) {
  const waiting = certificates.filter((c) => c.queue?.state === "queued");

  return (
    <div className="space-y-6">
      <RequestCertificate servers={servers} />

      {waiting.length > 0 && (
        <div className="card p-4">
          <div className="flex flex-wrap items-center gap-2">
            <Badge tone="amber">Queued</Badge>
            <p className="text-sm text-slate-300">
              {waiting.length === 1 ? "1 certificate request is" : `${waiting.length} certificate requests are`}{" "}
              waiting for earlier platform work to finish. Jobs run strictly one at a time, so this is a
              wait, not a failure — the position below updates on its own.
            </p>
          </div>
        </div>
      )}

      {certificates.length === 0 ? (
        <div className="card p-8 text-center text-sm text-slate-400">
          No certificates yet. Request one above to enable HTTPS on a domain pointed at your server.
        </div>
      ) : (
        <div className="card overflow-x-auto p-0">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Domain</th>
                <th>Server</th>
                <th>Status</th>
                <th>Expires (observed)</th>
                <th>Auto-renew &amp; actions</th>
              </tr>
            </thead>
            <tbody>
              {certificates.map((c) => (
                <tr key={c.id}>
                  <td className="max-w-sm font-medium text-slate-100">
                    {c.domain}
                    {c.lastError && (
                      <span
                        className={`mt-0.5 block text-xs font-normal ${
                          c.status === "FAILED" ? "text-red-400" : "text-amber-400"
                        }`}
                      >
                        {c.lastError}
                      </span>
                    )}
                  </td>
                  <td className="text-slate-400">{c.serverName ?? "—"}</td>
                  <td>
                    <StatusCell c={c} />
                  </td>
                  <td className="text-slate-400">
                    {c.expiresAt ? (
                      fmtDate(c.expiresAt)
                    ) : (
                      <span className="text-slate-500">not verified</span>
                    )}
                  </td>
                  <td>
                    <CertActions cert={c} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <p className="text-xs text-slate-500">
        Expiry dates are read from the certificate itself — at issuance, and again from what your
        domain actually serves on port 443. A certificate is only shown as active once a real expiry
        date has been observed.
      </p>
    </div>
  );
}

import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { AutoRefresh } from "@/components/AutoRefresh";
import { PageHeader } from "@/components/ui/primitives";
import {
  SslCertificates,
  type CertRow,
  type QueueInfo,
  type ServerOption,
} from "@/components/customer/SslCertificates";

export const dynamic = "force-dynamic";

type SslPayload = { certId?: string; domain?: string; renewal?: boolean };

export default async function SslPage() {
  const user = await requireUser();

  const [certificates, servers] = await Promise.all([
    db.sslCertificate.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
    }),
    db.server.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
    }),
  ]);

  const serverName = new Map(servers.map((s) => [s.id, s.hostname]));
  const myServerIds = new Set(servers.map((s) => s.id));

  // ---------------------------------------------------------------------------
  // Queue visibility.
  //
  // The worker claims ONE job at a time platform-wide — `worker/index.ts` picks
  // the oldest `status: "QUEUED"` row and awaits it inside a serial `for(;;)` —
  // so a certificate request genuinely can sit behind another tenant's long
  // MIGRATE. That happened on 2026-07-26: a request read "pending" for 13
  // minutes with nothing on screen to distinguish a queue from a crash, so the
  // customer had no way to know whether to wait or retry. Resolve the real
  // position here (this page already polls) instead of leaving them guessing.
  // ---------------------------------------------------------------------------
  const inflight = certificates.filter((c) => c.status === "PENDING" || c.status === "ISSUING");
  const queueByCert = new Map<string, QueueInfo>();

  if (inflight.length > 0) {
    const [sslJobs, running] = await Promise.all([
      db.job.findMany({
        where: { type: "SSL_ISSUE", status: { in: ["QUEUED", "RUNNING"] } },
        select: { id: true, status: true, createdAt: true, payload: true },
        orderBy: { createdAt: "asc" },
      }),
      // Whatever is holding the single worker slot right now.
      db.job.findFirst({
        where: { status: "RUNNING" },
        select: { type: true, serverId: true },
        orderBy: { createdAt: "asc" },
      }),
    ]);

    for (const cert of inflight) {
      const job = sslJobs.find((j) => ((j.payload ?? {}) as SslPayload).certId === cert.id);

      // No queued or running job at all: the request cannot make progress. Say so
      // rather than spinning — the reconcile sweep will age it out, and the row is
      // deletable in the meantime.
      if (!job) {
        queueByCert.set(cert.id, {
          state: "none",
          position: 0,
          aheadCount: 0,
          queuedAtIso: cert.createdAt.toISOString(),
          blocking: null,
        });
        continue;
      }

      if (job.status === "RUNNING") {
        queueByCert.set(cert.id, {
          state: "running",
          position: 0,
          aheadCount: 0,
          queuedAtIso: job.createdAt.toISOString(),
          blocking: null,
        });
        continue;
      }

      // FIFO by createdAt, matching the worker's claim order exactly.
      const aheadCount = await db.job.count({
        where: { status: "QUEUED", createdAt: { lt: job.createdAt } },
      });
      queueByCert.set(cert.id, {
        state: "queued",
        position: aheadCount + 1,
        aheadCount,
        queuedAtIso: job.createdAt.toISOString(),
        blocking: running
          ? {
              type: running.type,
              // Only the job type is exposed, never whose server it is beyond
              // "yours or not" — enough to explain the wait, nothing more.
              mine: running.serverId ? myServerIds.has(running.serverId) : false,
            }
          : null,
      });
    }
  }

  const rows: CertRow[] = certificates.map((c) => ({
    id: c.id,
    domain: c.domain,
    status: c.status,
    issuer: c.issuer,
    autoRenew: c.autoRenew,
    serverName: c.serverId ? serverName.get(c.serverId) ?? null : null,
    issuedAt: c.issuedAt ? c.issuedAt.toISOString() : null,
    // The observed notAfter, or null. Nothing here is ever a computed guess.
    expiresAt: c.expiresAt ? c.expiresAt.toISOString() : null,
    lastError: c.lastError,
    queue: queueByCert.get(c.id) ?? null,
  }));

  // Certificate issuance needs a live, DNS-pointed server, so only offer running ones.
  const serverOptions: ServerOption[] = servers
    .filter((s) => s.status === "RUNNING")
    .map((s) => ({ id: s.id, hostname: s.hostname }));

  const transitional = inflight.length > 0;

  return (
    <div className="space-y-6">
      {transitional && <AutoRefresh />}
      <PageHeader
        title="SSL Certificates"
        sub="One-click Let's Encrypt certificates for domains pointed at your servers. Renewed automatically from 21 days before expiry."
      />
      <SslCertificates certificates={rows} servers={serverOptions} />
    </div>
  );
}

