async function issueAttemptsFor(domain: string): Promise<{
  total: number;
  leRelevant: number;
  resumesAt: Date | null;
}> {
  const since = new Date(Date.now() - ISSUE_WINDOW_MS);
  const jobs = await db.job.findMany({
    where: { type: "SSL_ISSUE", createdAt: { gt: since } },
    select: { payload: true, step: true, createdAt: true },
    orderBy: { createdAt: "asc" },
  });
  let total = 0;
  let leRelevant = 0;
  let oldest: Date | null = null;
  for (const j of jobs) {
    if (payloadOf(j).domain !== domain) continue;
    total++;
    // `step === null` means in flight (or a pre-2026-07-26 job): count it against
    // the limit. When in doubt we protect the limit, not the convenience.
    if (j.step !== SSL_STEP_PREFLIGHT_FAILED && j.step !== SSL_STEP_SANDBOX) leRelevant++;
    if (!oldest) oldest = j.createdAt;
  }
  return {
    total,
    leRelevant,
    resumesAt: oldest ? new Date(oldest.getTime() + ISSUE_WINDOW_MS) : null,
  };
}

/** True when this hostname has used up its allowance for the current window. */
function rateLimited(rate: { total: number; leRelevant: number }): boolean {
  return (
    rate.leRelevant >= MAX_LE_ATTEMPTS_PER_WINDOW || rate.total >= MAX_TOTAL_ATTEMPTS_PER_WINDOW
  );
}

function rateLimitMessage(
  domain: string,
  rate: { total: number; leRelevant: number; resumesAt: Date | null }
): string {
  const when = rate.resumesAt
    ? `${rate.resumesAt.toISOString().slice(0, 16).replace("T", " ")} UTC`
    : "later this week";
  if (rate.leRelevant >= MAX_LE_ATTEMPTS_PER_WINDOW) {
    return (
      `${rate.leRelevant} certificate requests for ${domain} have already reached Let's Encrypt in the ` +
      `last 7 days. Let's Encrypt allows only 5 identical certificates per week, and going over would ` +
      `block new certificates for this domain for a full week — so we stop one short. You can try again ` +
      `after ${when}.`
    );
  }
  return (
    `${rate.total} attempts for ${domain} have failed in the last 7 days before ever reaching Let's ` +
    `Encrypt, so another attempt would fail the same way. Fix the error shown on the certificate first; ` +
    `you can try again after ${when}.`
  );
}

